private string GetChromeExePath()
{
    string strPath = null;
    try
    {
        strPath = DCore.Globals.GetConfig("ChromeExePath");
    }
    catch
    {
    }

    if (!string.IsNullOrEmpty(strPath) && File.Exists(strPath))
        return strPath;

    strPath = @"C:\Program Files\Google\Chrome\Application\chrome.exe";
    if (File.Exists(strPath))
        return strPath;

    strPath = @"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe";
    if (File.Exists(strPath))
        return strPath;

    strPath = @"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe";
    if (File.Exists(strPath))
        return strPath;

    return @"C:\Program Files\Google\Chrome\Application\chrome.exe";
}

private string BuildPrintHtmlDocument()
{
    string strClassTitle = "";
    if (UClass1.ClassName != null && UClass1.ClassName != "")
        strClassTitle = "<div class='class-name'>Lớp: " + HttpUtility.HtmlEncode(UClass1.ClassName) + "</div>";

    return "<!DOCTYPE html><html><head><meta http-equiv='Content-Type' content='text/html; charset=utf-8'/>"
        + "<title>Thời khóa biểu tuần</title>"
        + "<style>"
        + "body{font-family:'Times New Roman',Times,serif;font-size:12px;margin:12px;color:#000;}"
        + ".title-4{text-align:center;font-size:16px;font-weight:bold;margin:8px 0;text-transform:uppercase;}"
        + ".title-5{text-align:center;font-size:13px;margin-bottom:12px;}"
        + ".class-name{text-align:center;font-size:14px;font-weight:bold;margin-bottom:10px;}"
        + ".table-responsive{width:100%;}"
        + "table.table{width:100%;border-collapse:collapse;text-align:center;font-size:11px;}"
        + "table.table td,table.table th{border:1px solid #333;padding:3px;vertical-align:middle;word-break:break-word;white-space:normal;}"
        + "thead.table-primary-2 td,thead.table-primary-2 th{background:#147a4e;color:#fff;font-weight:bold;}"
        + "</style></head><body>"
        + strClassTitle
        + _htmlTitle
        + _htmlContent
        + "</body></html>";
}

private bool OpenExportPdf()
{
    if (string.IsNullOrEmpty(_htmlContent))
    {
        MsgBox.ShowWarning("Không có dữ liệu thời khóa biểu để in!");
        return false;
    }

    string strBasePath = AppDomain.CurrentDomain.BaseDirectory;
    string strFileNameHtml = WebGlobal.FilterFileName(String.Format("TKB_{0}_Tuan{1}_{2}.html",
        UClass1.ClassID,
        (intWeek + 1).ToString(),
        DateTime.Now.ToString("yyMMddHHmmss")));
    string strPathHtml = Path.Combine(strBasePath, "Export", strFileNameHtml);
    string strPathPdf = Path.ChangeExtension(strPathHtml, ".pdf");
    string strFileNamePdf = Path.GetFileName(strPathPdf);

    try
    {
        Directory.CreateDirectory(Path.GetDirectoryName(strPathHtml));
        File.WriteAllText(strPathHtml, BuildPrintHtmlDocument(), Encoding.UTF8);

        if (!Libs.ChromePdfHelper.ConvertToPdf(strPathHtml, strPathPdf, GetChromeExePath()))
        {
            MsgBox.ShowError("Không thể chuyển HTML sang PDF. Kiểm tra Chrome/Edge trên máy chủ.");
            return false;
        }

        if (File.Exists(strPathHtml))
            File.Delete(strPathHtml);
    }
    catch (Exception ex)
    {
        MsgBox.ShowError("Lỗi khi tạo file PDF. " + ex.Message);
        return false;
    }

    string strUrl = "/Export/" + strFileNamePdf
        + "?time=" + DateTime.Now.ToString("yyMMddHHmmss");

    ScriptManager.RegisterStartupScript(Page, Page.GetType(), "_OpenScheduleOfClassPdf",
        String.Format("window.open('{0}','_blank');", strUrl), true);

    return true;
}

protected void btnPrint_Click(object sender, EventArgs e)
{
    if (string.IsNullOrEmpty(UClass1.ClassID))
    {
        MsgBox.ShowWarning("Bạn phải chọn lớp học!");
        return;
    }
    if (ddlWeek.SelectedValue == "")
